const usuario = {
  perfil: { nombre: 'Ada', ciudad: 'Madrid' },
};
const copia = {
  ...usuario,
  perfil: { ...usuario.perfil, ciudad: 'Bilbao' },
};
usuario.perfil.ciudad + '|' + copia.perfil.ciudad;

function cambiarCiudad(usuario, ciudad) {
  const copia = { ...usuario };
  copia.perfil.ciudad = ciudad;
  return copia;
}

function actualizarCiudad(usuario, ciudad) {
  usuario.perfil.ciudad = ciudad;
  return usuario;
}
